def gen(rng):
    def fmt(n, missing):
        return '%d\n%s' % (n, ' '.join(str(i) for i in range(1, n + 1) if i != missing))
    tests = [fmt(2, 1), fmt(2, 2), fmt(3, 1), fmt(3, 2), fmt(3, 3), fmt(10, 10), fmt(10, 1), fmt(10, 5)]
    for _ in range(25):
        n = rng.randint(2, 60)
        tests.append(fmt(n, rng.randint(1, n)))
    N = 300000
    tests.append(fmt(N, 1))
    tests.append(fmt(N, N // 2))
    tests.append(fmt(N, N))
    tests.append(fmt(N - 1, rng.randint(1, N - 1)))
    return tests

